 83	/** Deterministic permutation, different at every step. */
 84	const permute = <T>(items: T[], seed: number): T[] => {
 85	  const copy = [...items];
 86	  let state = seed;
 87	  for (let index = copy.length - 1; index > 0; index -= 1) {
 88	    state = (state * 1103515245 + 12345) % 2147483648;
 89	    const swap = state % (index + 1);
 90	    [copy[index], copy[swap]] = [copy[swap]!, copy[index]!];
 91	  }
 92	  return copy;
 93	};
